"""Write LABEL_ME.md from cases.jsonl: a sheet for the human assessor to fill in blind.""" import json from pathlib import Path HERE = Path(__file__).parent cases = [json.loads(l) for l in open(HERE / "cases.jsonl", encoding="utf-8")] out = ["""# Label these 15 grants (blind: don't run the skill first) Edit each `LABEL:` line: `theme | beneficiary | funding_type | outcome_stated | score` - theme: housing, health_wellbeing, employment_skills, energy_environment, arts_culture, community_places, criminal_justice, youth_education, poverty_finance, other - beneficiary: children_young_people, older_people, people_in_poverty, disabled_people, ethnic_minority_communities, general_community, organisations_sector, unclear - funding_type: core_costs, project, social_investment, other - outcome_stated: true only if the record states an intended change for people/places, not just an activity - score 1-5: how clearly the RECORD supports an impact case (1 nothing stated; 3 beneficiary+activity clear, outcome vague; 5 beneficiary, outcome and scale clear) - Judge only from the text shown. If the text says nothing, that is a 1. """] for c in cases: out.append(f"## #{c['id']} {c['funder']} £{c['amount']:,.0f} {c['award_date']}
" f"**Recipient:** {c['recipient']}
**Title:** {c['title']}
**Description:** {c['description']}

" f"LABEL: ? | ? | ? | ? | ?
") (HERE / "LABEL_ME.md").write_text("
".join(out), encoding="utf-8") print("ok", len(cases))

def record_text(c: dict) -> str: return ( f"Funder: {c['funder']}
Recipient: {c['recipient']}
Amount: GBP {c['amount']:,.0f}
" f"Award date: {c['award_date']}
Title: {c['title']}
Description: {c['description']}" )

def judge(model: str, c: dict, out: dict) -> dict: payload = f"RECORD:
{record_text(c)}

SCREEN OUTPUT:
{json.dumps(out, ensure_ascii=False)}" v = parse_json(chat(model, JUDGE_SYSTEM, payload, 2500)) return v if v and isinstance(v.get("grounded"), bool) else {"unsupported": [], "grounded": None, "error": "judge returned invalid JSON"}

"""Draw a seeded, stratified sample of grants as unlabelled eval cases (eval/cases.jsonl).""" import json import sqlite3 from pathlib import Path import pandas as pd HERE = Path(__file__).parent df = pd.read_sql("SELECT * FROM grants WHERE amount > 0", sqlite3.connect(HERE.parent / "data" / "grants.sqlite")) df["dlen"] = df["description"].fillna("").str.len() df = df[(df["dlen"] >= 40) & (df["dlen"] <= 600)] parts = [g.sample(3, random_state=7) for _, g in df.groupby("funder")] cases = pd.concat(parts).reset_index(drop=True) with open(HERE / "cases.jsonl", "w", encoding="utf-8") as f: for i, r in cases.iterrows(): rec = {"id": i + 1, **{k: r[k] for k in ["grant_id", "funder", "recipient", "amount", "award_date", "title", "description"]}, "label": {"theme": None, "beneficiary": None, "funding_type": None, "outcome_stated": None, "impact_case_score": None}} f.write(json.dumps(rec, ensure_ascii=False, default=str) + "
") print(f"#{rec['id']} [{r['funder'][:12]}] £{r['amount']:,.0f} {r['award_date']} | {r['recipient']}
 {r['title']}
 {r['description'][:420]}
")
